function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function changed(renderNow=false){if(worker){worker.terminate();worker=null;setRunning(false);toast('Inputs changed; current analysis cancelled.');}results=null;sensitivity=null;reportPreferences=null;$('#status').textContent='Inputs changed · analysis required';saveLocal();if(renderNow)render();}
function saveLocal(){try{localStorage.setItem('loss-lab-project-v1',JSON.stringify(p));$('#saveStatus').textContent='Saved on this browser';}catch{$('#saveStatus').textContent='Autosave unavailable / storage full · download project';}}
function download(name,content,type='application/json'){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function nameSafe(s){return String(s).replace(/[^\w-]+/g,'_').slice(0,80)||'study';}
const names=()=>Object.keys(p.waveforms[0]?.columns||{}),options=(list,value,blank=false)=>`${blank?'<option value="">Select signal…</option>':''}`+list.map(s=>`<option value="${esc(s)}" ${s===value?'selected':''}>${esc(s)}</option>`).join('');
function characteristicOptions(list,value){return list.map(id=>`<option value="${id}" ${id===value?'selected':''}>${esc(characteristicName(id))}</option>`).join('');}
function dependencyFields(id,values={},prefix='digit'){return dependencies(id).map(k=>`<label>${QUANTITIES[k][0]} [${QUANTITIES[k][1]}]<input type="number" step="any" data-dependency="${k}" data-prefix="${prefix}" value="${esc(values[k]??'')}"></label>`).join('')||'<p class="caption">No additional operating dependencies for this characteristic.</p>';}
function input(label,path,value,type='number',extra=''){return `<div><label>${label}<input type="${type}" data-path="${path}" value="${esc(value??'')}" ${extra}></label></div>`;}
function select(label,path,value,list){return `<div><label>${label}<select data-path="${path}">${options(list,value)}</select></label></div>`;}
function check(label,path,value){return `<label class="check"><input type="checkbox" data-path="${path}" ${value?'checked':''}>${label}</label>`;}
function heading(eyebrow,title,desc,right=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${right}</div>`;}
function panel(title,body,right=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${right}</div>${body}</section>`;}
function empty(title,text){return `<div class="empty"><strong>${title}</strong>${text}</div>`;}
function metric(label,value,unit,hint,highlight=false){return `<div class="metric"><div class="label">${label}</div><div class="value ${highlight?'lime':''}">${value}<small>${unit}</small></div><div class="hint">${hint}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function axisTick(v,span){const digits=Math.max(0,Math.min(12,2-Math.floor(Math.log10(Math.abs(span)||1))));return num(v,digits);}
function graph(series,{xLabel='Output power [W]',yLabel='Efficiency [%]',width=680,height=270,guidePoints=[]}={}){let pts=series.flatMap(s=>s.points).filter(a=>Number.isFinite(a[0])&&Number.isFinite(a[1]));if(!pts.length)return empty('No plot available','Run a valid analysis or load waveform data.');let xmin=Math.min(...pts.map(a=>a[0])),xmax=Math.max(...pts.map(a=>a[0])),ymin=Math.min(...pts.map(a=>a[1])),ymax=Math.max(...pts.map(a=>a[1]));if(xmin===xmax){xmin-=.5;xmax+=.5;}let pad=(ymax-ymin)*.15||Math.max(Math.abs(ymax)*.05,.1);ymin-=pad;ymax+=pad;let L=62,R=22,T=18,B=42,X=v=>L+(v-xmin)/(xmax-xmin)*(width-L-R),Y=v=>height-B-(v-ymin)/(ymax-ymin)*(height-T-B);let s=`<svg viewBox="0 0 ${width} ${height}" class="chart" role="img" aria-label="${esc(yLabel+' versus '+xLabel)}">`;for(let j=0;j<5;j++){let y=ymin+(ymax-ymin)*j/4;s+=`<path class="grid" d="M${L},${Y(y)}H${width-R}"/><text x="${L-8}" y="${Y(y)+4}" text-anchor="end">${axisTick(y,ymax-ymin)}</text>`;}for(let j=0;j<5;j++){let x=xmin+(xmax-xmin)*j/4;s+=`<text x="${X(x)}" y="${height-B+18}" text-anchor="middle">${axisTick(x,xmax-xmin)}</text>`;}
 guidePoints.filter(a=>a.every(Number.isFinite)).forEach(a=>{s+=`<path d="M${L},${Y(a[1])}H${X(a[0])}V${height-B}" stroke="#ffb454" stroke-width="1.5" stroke-dasharray="5 4" fill="none"/>`;});series.forEach((r,j)=>{let points=r.points.filter(a=>a.every(Number.isFinite)),color=r.color||colors[j%colors.length];if(!r.scatter)s+=`<polyline class="line" stroke="${color}" points="${points.map(a=>`${X(a[0])},${Y(a[1])}`).join(' ')}"/>`;if(points.length<70||r.scatter)points.forEach(a=>s+=`<circle cx="${X(a[0])}" cy="${Y(a[1])}" r="${r.selected?6:3}" stroke="${r.selected?'#fff':color}" stroke-width="${r.selected?2:0}" fill="${color}"><title>${esc(r.name)}: ${a[0]}, ${a[1]}</title></circle>`);});s+=`<text x="${width/2}" y="${height-3}" text-anchor="middle">${esc(xLabel)}</text><text transform="translate(13 ${height/2}) rotate(-90)" text-anchor="middle">${esc(yLabel)}</text></svg><div class="legend">${series.map((r,j)=>r.name?`<span><i style="background:${r.color||colors[j%colors.length]}"></i>${esc(r.name)}</span>`:'').join('')}</div>`;return s;}
function efficiencyGraph(rows){let groups=new Map();orderedOperatingPoints(rows).filter(r=>r.valid).forEach(r=>{const k=`${r.combination}:${r.vin}:${r.vout}`;let g=groups.get(k)||{name:`Combination ${r.combination} · ${num(r.vin,2)} / ${num(r.vout,2)} V`,points:[]};g.points.push([r.outputPower,r.efficiency]);groups.set(k,g);});return graph([...groups.values()].map(g=>({...g,points:g.points.sort((a,b)=>a[0]-b[0])})));}
function breakdown(cats){let sum=CATEGORIES.reduce((s,k)=>s+(cats?.[k]||0),0);return CATEGORIES.map((k,j)=>`<div class="barrow"><span>${LABELS[k]}</span><div class="track"><div class="fill" style="width:${sum?100*(cats[k]||0)/sum:0}%;background:${colors[j]}"></div></div><span class="num">${num(cats?.[k])} W</span></div>`).join('');}
function getInst(){return p.instances.find(i=>i.id===selectedInstance)||p.instances[0];}function getCand(){const inst=getInst();return inst?.candidates.find(c=>c.id===selectedCandidate)||inst?.candidates[0];}
function openDigitiser(group){pendingDigitGroup=group;digit={image:null,imageData:null,calibration:[],points:[],zoom:1,stage:'calibrate',group,curveId:group?lossCharacteristicIds(group).find(k=>k!=='Constant_ESR'):undefined};digitOpen=true;render();}
function render(){page=location.hash.slice(1)||'overview';if(page==='digitizer')page='devices';if(!['overview','waveforms','devices','results','guide'].includes(page))page='overview';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#projectName').value=p.name;$('#waveCount').textContent=p.waveforms.length;$('#deviceCount').textContent=p.instances.length;$('#page').innerHTML=({overview,waveforms,devices,results:resultsPage,guide})[page]();$('#digitOverlay')?.remove();if(digitOpen){const overlay=document.createElement('dialog');overlay.id='digitOverlay';overlay.innerHTML=digitizerPage();document.body.append(overlay);overlay.oncancel=e=>{e.preventDefault();digitOpen=false;render();};overlay.showModal();}bind();if(digitOpen)drawDigit();}

function overview(){const best=results?.best,bestRows=results?.rows.filter(r=>r.combination===best?.combination)||[],meanCats=bestRows.length?Object.fromEntries(CATEGORIES.map(k=>[k,bestRows.reduce((s,r)=>s+r.categories[k],0)/bestRows.length])):null,nComb=p.instances.length?p.instances.reduce((s,i)=>s*i.candidates.length,1):0;
 return heading('CONVERTER STUDY','From waveforms to design decisions.','Compare device alternatives with traceable, waveform-driven loss calculations.',`<span class="tag ${p.waveforms.some(w=>w.demo)?'orange':'green'}">${p.waveforms.some(w=>w.demo)?'Synthetic demo':'Your study'}</span>`)+
 `<div class="metrics">${metric('BEST AVERAGE EFFICIENCY',num(best?.meanEfficiency,3),'%',best?'Combination '+best.combination+' · included losses only':'Run analysis to compare alternatives',true)}${metric('AVERAGE TOTAL LOSS',num(best?.meanLoss,3),'W','Across all valid operating points')}${metric('COMPONENT ALTERNATIVES',num(nComb),'combinations',p.instances.length+' instances · unique alternatives')}${metric('OPERATING POINTS',p.waveforms.length,'files','Signed real output power')}</div>`+
 (p.importNotes?.length?`<div class="notice ${p.waveforms.some(w=>w.demo)?'warn':''}">${p.importNotes.map(esc).join('<br>')}</div>`:'')+
 `<div class="grid2">${panel('Efficiency across operating points',results?efficiencyGraph(results.rows):demoWaveGraph(),`<span class="tag">${results?'ANALYSIS RESULTS':'WAVEFORM PREVIEW'}</span>`)}${panel('Loss distribution',meanCats?breakdown(meanCats):`<p class="caption">Run the study to compare conduction, switching and passive losses.</p><div class="scope-list">${CATEGORIES.map((k,j)=>`<span style="color:${colors[j]}">● ${LABELS[k]}</span>`).join('')}</div>`)}</div>`+
 panel('Your engineering workflow',`<div class="steps">${[['01','Import waveforms','CSV, TXT, MAT or JSON','waveforms'],['02','Define components','Curves, mappings & alternatives','devices'],['03','Digitise datasheets','Open a component loss model','devices'],['04','Compare & export','Losses, thermal results & reports','results']].map(a=>`<div class="step" data-nav="${a[3]}" tabindex="0" role="link"><div class="number">${a[0]}</div><b>${a[1]}</b><span>${a[2]}</span></div>`).join('')}</div>`)+
 `<div class="grid-equal">${panel('Analysis settings',opForm())}${panel('Included components',p.instances.map(i=>`<div class="component"><div class="icon">${i.type==='MOSFET'?'Q':i.type[0]}</div><div class="name"><strong>${esc(i.name)}</strong><small>${i.type} · ${i.candidates.length} candidate${i.candidates.length===1?'':'s'}</small></div><button class="ghost small" data-instance="${i.id}">Edit ↗</button></div>`).join('')||empty('Start a study','Add components from the component editor.'))}</div>`;
}
function demoWaveGraph(){let w=p.waveforms[0];if(!w)return empty('No waveforms imported','Import simulation results or load the synthetic demo.');let t=w.columns[w.time],current=Object.keys(w.columns).find(k=>/^i/i.test(k));return graph([{name:current||w.time,points:t.map((v,j)=>[v,current?w.columns[current][j]:v]).filter((_,j)=>j%Math.max(1,Math.floor(t.length/700))===0)}],{xLabel:'Time [s]',yLabel:current?'Current [A]':'Time [s]'});}
function opForm(){return `<div class="form-grid two">${select('Conversion mode','op.mode',p.operating.mode,['DC/DC','AC/DC','DC/AC','AC/AC'])}${input('Analysis window [s]','op.window',p.operating.window,'number','min="0" step="any"')}<label>Interpolation method<select data-path="op.interpolationMethod">${Object.entries(INTERPOLATION_METHODS).map(([id,label])=>`<option value="${id}" ${(p.operating.interpolationMethod||'reference-first')===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${select('Out-of-domain policy','op.domainPolicy',p.operating.domainPolicy,['error','clamp','extrapolate','matlab'])}${select('Spectral samples','op.fftSize',String(p.operating.fftSize),['256','512','1024','2048','4096'])}</div><p class="caption">The last window is used. Boundary samples are interpolated. Strict domain checking is the default. Forward-first applies to inverse queries and rejects ambiguous combined curves. Weighted averaging uses normalised dependency distances and is a heuristic. Select “matlab” to use the original tool’s linear curve extrapolation, first-point duplicate handling and Vgs / temperature interpolation.</p><details class="method-help"><summary>How interpolation and domain policies work</summary><p><b>Reference curves first:</b> query each reference curve (including inversion when needed), then interpolate the returned values between dependency conditions. This follows the existing MATLAB ordering.</p><p><b>Forward family first:</b> interpolate the forward curves at the requested dependencies, then invert the combined curve. Nonmonotonic or flat inverse branches are rejected.</p><p><b>Weighted average:</b> combine curve query results using inverse squared distances in normalised dependency coordinates. Exact reference conditions take precedence. This is a heuristic, not linear grid interpolation.</p><p><b>Error:</b> reject queries outside a sampled curve or varying dependency range. <b>Clamp:</b> use the nearest boundary. <b>Extrapolate:</b> extend the boundary segment linearly. <b>MATLAB:</b> use the original compatibility rules, including linear curve extrapolation and first-point duplicate handling. A single dependency reference is fixed, not an inferred temperature model; assumptions are recorded in diagnostics.</p></details><h3>Output power mapping</h3>${pairForm('outputPairs')}${check('Balanced three-phase output: one mapped phase × 3','op.balancedOutput',p.operating.balancedOutput)}<h3>Input voltage / current mapping</h3>${pairForm('inputPairs')}${check('Balanced three-phase input: one mapped phase × 3','op.balancedInput',p.operating.balancedInput)}<p class="caption">For AC use phase-to-neutral voltages paired with phase currents. Reverse the output polarity for regeneration studies so delivered power is positive.</p>`;}
function pairForm(side){return p.operating[side].map((r,j)=>`<div class="form-grid"><div><label>Voltage ${j+1}<select data-path="op.${side}.${j}.v">${options(names(),r.v,true)}</select></label></div><div><label>Current ${j+1}<select data-path="op.${side}.${j}.i">${options(names(),r.i,true)}</select></label></div><div><label>Power polarity<select data-path="op.${side}.${j}.polarity">${options(['1','-1'],String(r.polarity??1))}</select></label></div></div>`).join('')+`<button class="ghost small" data-add-pair="${side}">+ Phase pair</button> <button class="ghost small" data-remove-pair="${side}">− Last pair</button>`;}
function waveforms(){let w=p.waveforms.find(w=>w.id===selectedWave)||p.waveforms[0],keys=w?Object.keys(w.columns):[],selectedSignal=w?.viewSignal||keys.find(k=>k!==w.time),points=w&&selectedSignal?w.columns[w.time].map((v,j)=>[v,w.columns[selectedSignal][j]]).filter((_,j)=>j%Math.max(1,Math.ceil(w.columns[w.time].length/1200))===0):[];return heading('SIMULATION & TEST DATA','Waveforms','Import each operating point, confirm units and inspect the time-domain signals.',`<button id="importWave" class="primary">+ Import files</button>`)+
 `<div class="dropzone" id="waveDrop"><strong>Drop waveform files here</strong>CSV / TXT with headers · numeric MAT level-5 · JSON columns</div>`+
 `<div class="grid2">${panel('Operating-point files',table(['File','Samples','Time [s]',''],p.waveforms.map(q=>`<tr><td><button class="ghost small" data-wave="${q.id}">${esc(q.name)}</button>${q.demo?' <span class="tag orange">DEMO</span>':''}</td><td class="num">${q.columns[q.time]?.length??0}</td><td class="num">${num(q.columns[q.time]?.at(-1),6)}</td><td><button class="ghost small danger" data-delete-wave="${q.id}">Remove</button></td></tr>`)))}${panel('Import requirements',`<p class="caption">Time must be finite, strictly increasing and in seconds. Voltage and current must be in volts and amps. Unit conversion is available per file before import.</p><p class="caption">No missing values or mismatched columns are silently accepted. Every file must contain the mapped signals used by the study.</p><button class="ghost small" id="downloadSample">↓ Example CSV</button> <a class="small" href="export_loss_tool_web.m" download>MATLAB export helper ↓</a>`)}</div>`+
 (w?panel('Signal inspection',`<div class="form-grid">${input('Operating point name','wave.name',w.name,'text')}<div><label>Time column<select data-path="wave.time">${options(keys,w.time)}</select></label></div><div><label>Inspect signal<select id="viewSignal">${options(keys,selectedSignal)}</select></label></div></div>${graph([{name:selectedSignal,points}],{xLabel:'Time [s]',yLabel:selectedSignal===w.time?'Time [s]':/^[iI]|current/i.test(selectedSignal)?'Current [A]':'Signal amplitude'})}<div class="toolbar"><button class="ghost small" id="waveCSV">↓ Export file as CSV</button><span class="caption">Plot decimated for display; calculations use the full imported samples.</span></div>${table(keys.slice(0,12),Array.from({length:Math.min(8,w.columns[w.time].length)},(_,j)=>'<tr>'+keys.slice(0,12).map(k=>`<td class="num">${num(w.columns[k][j],7)}</td>`).join('')+'</tr>'))}`):'')+panel('Operating conditions',opForm());}
function devices(){let inst=getInst(),c=getCand();if(inst){selectedInstance=inst.id;selectedCandidate=c.id;}return heading('COMPONENT MODELS','Components & curves','Define each device bank, import datasheet characteristics and compare candidate parts.',`<button class="ghost" id="importComponent">↑ Import alternative JSON</button><button class="primary" id="addInstance">+ Add component</button>`)+`<div class="device-layout"><div class="device-nav">${p.instances.map(i=>`<button class="${i.id===inst?.id?'selected':''}" data-select-instance="${i.id}">${esc(i.name)}<span class="caption" style="display:block">${i.type} · ${i.candidates.length} alternatives</span></button>`).join('')}</div><div>${inst?panel(esc(inst.name),`<div class="form-grid">${input('Instance name','inst.name',inst.name,'text')}<div><label>Candidate<select id="candidateSelect">${inst.candidates.map(q=>`<option value="${q.id}" ${q.id===c.id?'selected':''}>${esc(q.part)}</option>`).join('')}</select></label></div><div class="toolbar"><button class="ghost small" id="addCandidate">+ Alternative</button><button class="ghost small" id="importAlternative">↑ Import alternative</button><button class="ghost small danger" id="deleteCandidate">Remove</button></div></div><div class="subtabs">${['settings','curves','thermal'].map(k=>`<button data-subtab="${k}" class="small ${subtab===k?'active':''}">${k==='curves'?'Loss models & curves':k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div>${subtab==='settings'?candidateSettings(inst,c):subtab==='thermal'?thermalForm(c):curveList(c)}<div class="toolbar"><button class="ghost small" id="exportComponent">↓ Export alternative JSON</button><button class="ghost small danger" id="deleteInstance">Remove instance</button></div>`):panel('Create a component',empty('No components yet','Add a MOSFET, diode, capacitor or inductor to start.'))}</div></div>`;}
function candidateSettings(inst,c){let cats=inst.type==='MOSFET'?['conduction','body','on','off','recovery']:inst.type==='Diode'?['conduction','recovery']:inst.type==='Inductor'?['copper','core']:['copper'];return `<div class="form-grid">${input('Part / candidate name','cand.part',c.part,'text')}${input('Devices in series','cand.series',c.series,'number','min="1" step="1"')}${input('Devices in parallel','cand.parallel',c.parallel,'number','min="1" step="1"')}${input('Total physical device count','cand.totalCount',c.totalCount,'number','min="1" step="1"')}<div><label>Current orientation<select data-path="inst.currentPolarity">${options(['1','-1'],String(inst.currentPolarity??1))}</select></label></div></div>${check('Additional replicated banks: confirm total count differs from series × parallel','cand.replicationConfirmed',c.replicationConfirmed)}<h3>Waveform mapping</h3><div class="form-grid">${['current','voltage',...(inst.type==='MOSFET'?['gate']:[])].map(k=>`<div><label>${k[0].toUpperCase()+k.slice(1)} signal<select data-path="inst.mapping.${k}">${options(names(),inst.mapping[k],true)}</select></label></div>`).join('')}</div><p class="caption">Mapped current is divided by parallel count; voltage by series count. Losses are multiplied by total physical devices. Diode current/voltage use forward-positive orientation. MOSFET current uses drain-to-source positive orientation.</p><h3>Included loss contributions</h3><div class="scope-list">${cats.map(k=>`<label class="check"><input type="checkbox" data-enable="${k}" ${c.enabled.includes(k)?'checked':''}>${LABELS[k]}</label>`).join('')}</div><p class="caption">Disabled categories are explicitly excluded. Enabled categories with missing data invalidate this candidate instead of becoming zero.</p>`+
 (inst.type==='MOSFET'?`<h3>Gate and switching parameters</h3><div class="form-grid">${select('Gate waveform','cand.gateType',c.gateType,['logic','analog'])}${input('Logic on Vgs [V]','cand.vgsOn',c.vgsOn)}${input('Logic off Vgs [V]','cand.vgsOff',c.vgsOff)}${input('Analog on threshold [V]','cand.gateOn',c.gateOn)}${input('Analog off threshold [V]','cand.gateOff',c.gateOff)}${input('Rg turn-on [Ω]','cand.rgOn',c.rgOn)}${input('Rg turn-off [Ω]','cand.rgOff',c.rgOff)}</div><p class="caption">Analog thresholds provide hysteresis. Reverse gate-on current is assigned to channel conduction; gate-off reverse current to the body path.</p>`:'')+
 (cats.includes('recovery')?check('Recovery definition reviewed: Err / Qrr model applies and is not already counted in Eon','cand.recoveryConfirmed',c.recoveryConfirmed):'')+
 (inst.type==='Inductor'?`<h3>Magnetic model</h3><div class="form-grid">${input('Turns N','cand.N',c.N)}${input('Effective area Ae [m²]','cand.Ae',c.Ae,'number','step="any"')}${input('Core volume [m³]','cand.Vcore',c.Vcore,'number','step="any"')}${input('Initial / bias flux [T]','cand.B0',c.B0)}${input('Core excitation frequency [Hz] · 0 = detect','cand.coreFrequency',c.coreFrequency)}${input('DC winding resistance [Ω]','cand.dcResistance',c.dcResistance,'number','step="any"')}</div>${check('Use sinusoidal-equivalent core estimate: PWM, DC bias and minor-loop accuracy is not established','cand.coreApproxConfirmed',c.coreApproxConfirmed)}<p class="caption">Constant ESR uses time-weighted I²R. Frequency-dependent resistance uses a harmonic sum; the DC component uses the DC winding resistance.</p>`:'');}
function thermalForm(c){return `<div class="form-grid">${select('Temperature model','cand.thermal.mode',c.thermal.mode,['fixed','iterative'])}${input(c.thermal.mode==='fixed'?'Device temperature [°C]':'Ambient / reference temperature [°C]','cand.thermal.temperature',c.thermal.temperature)}${input('Thermal resistance [K/W]','cand.thermal.Rth',c.thermal.Rth,'number','min="0" step="any"')}${select('Rth represents','cand.thermal.scope',c.thermal.scope,['device','bank'])}${input('Maximum permitted temperature [°C]','cand.thermal.maxTemperature',c.thermal.maxTemperature)}</div><div class="notice">Per-device Rth uses one device’s loss. Bank Rth uses all devices’ losses. Shared heatsink coupling is not represented by independent candidate models.</div><p class="caption">The solver is damped, checks convergence and returns a failed result on divergence or temperature-limit violation. Temperature-dependent curves are evaluated at each iteration.</p>`;}
