function debugPanel(rows){const choices=orderedOperatingPoints(rows).flatMap(r=>r.devices.filter(d=>d.valid).map(d=>({key:r.waveformId+':'+d.candidateId,r,d}))),sel=choices.find(v=>v.key===p.debugSelection)||choices[0];if(!sel)return empty('No valid device results','Resolve missing data first.');const inst=p.instances.find(i=>i.id===sel.d.instanceId),candidate=inst?.candidates.find(c=>c.id===sel.d.candidateId),curves=candidate?.curves.filter(c=>c.constant===undefined)||[],cr=curves.find(c=>c.id===p.debugCurve)||curves[0],queries=(sel.d.queries||[]).filter(q=>q.curveId===cr?.id);debugState={device:sel.d,curve:cr,queries};debugQueryIndex=Math.max(0,Math.min(debugQueryIndex,queries.length-1));return `<div class="form-grid two"><label>Device / operating point<select id="debugSelection">${choices.map(v=>`<option value="${v.key}" ${sel.key===v.key?'selected':''}>${esc(operatingPointLabel(v.r)+' · '+v.d.instanceName+' · '+v.d.part)}</option>`).join('')}</select></label><label>Characteristic<select id="debugCurve">${curves.map(c=>`<option value="${c.id}" ${c.id===cr?.id?'selected':''}>${esc(c.sourceId?characteristicName(c.sourceId):c.yName+' vs '+c.xName)}</option>`).join('')}</select></label></div><p class="caption">Each characteristic keeps its own sampled queries, including short body-diode intervals. Markers and tables use the same engine query record. Switching current and blocking voltage can come from different samples.</p>${queries.length?`<label>Query / event<select id="debugQuery">${queries.map((q,j)=>`<option value="${j}" ${j===debugQueryIndex?'selected':''}>${j+1} · ${esc(q.category||'model')} · ${num(q.time_s,12)} s · ${num(q.input,8)} ${esc(q.given)}</option>`).join('')}</select></label><label>Move through this loss contribution<input id="debugQueryRange" type="range" min="0" max="${queries.length-1}" step="1" value="${debugQueryIndex}"></label>`:''}<div id="debugDetail">${queries.length?inspectDetail():empty('No queries for this characteristic','This model was not queried in the selected window.')}</div>`;}

