 for(const id of ['digitId','dxmin','dxmax','dymin','dymax','dxscale','dyscale','dxunit','dyunit','digitRbase','digitSource'])if($('#'+id))$('#'+id).onchange=()=>{digitSettings();if(id==='digitId'){const [x,y]=CURVE_IDS[digit.curveId];digit={image:null,imageData:null,calibration:[],points:[],zoom:1,stage:'calibrate',curveId:digit.curveId,group:digit.group};render();}else $('#digitPreview').innerHTML=digitPreview();};document.querySelectorAll('[data-prefix="digit"]').forEach(el=>el.onchange=()=>digitSettings());
 click('digitDone',()=>{if(digit.points.length){$('#digitSave').click();if(digit.points.length)return;}digitOpen=false;render();});click('digitSave',()=>{try{digitSettings();if(!digit.xunit||!digit.yunit)throw Error('Choose both axis units');let data=digitData();if(digit.points.length<2||data.length<2)throw Error('Sample at least two points');if(!getCand())throw Error('Add a component first');let deps=digit.deps;if(!deps||!Object.values(deps).every(Number.isFinite))throw Error('Enter finite numbers for all operating dependencies');let [xName,yName]=CURVE_IDS[digit.curveId],sourceId=digit.curveId;if(xName==='ESR_normalised')xName='ESR';if(yName==='ESR_normalised')yName='ESR';if(data.some((a,j)=>j&&a[0]===data[j-1][0]))throw Error('Duplicate X points: remove a sample or choose a single branch');let c=getCand(),cr=c.curves.find(q=>q.sourceId===sourceId),iteration={x:data.map(a=>a[0]),y:data.map(a=>a[1]),deps,provenance:{imageData:digit.imageData,calibration:digit.calibration,rawPixels:structuredClone(digit.points),rawSI:digitOrigin().raw,origin:{policy:digitOrigin().policy,addedPoint:digitOrigin().origin},limits:[digit.xmin,digit.xmax,digit.ymin,digit.ymax],xScale:digit.xscale,yScale:digit.yscale,source:digit.source}};if(!cr){cr={id:uid('curve'),sourceId,xName,yName,canonicalSI:true,voltageScaling:/Eon|Eoff/.test(sourceId)&&digit.voltageScaling,iterations:[],provenance:{source:digit.source||'Image digitisation'}};c.curves.push(cr);}if(/Eon|Eoff/.test(sourceId))cr.voltageScaling=digit.voltageScaling;cr.iterations.push(iteration);if(digit.group){c.lossModels??={};c.lossModels[digit.group]=cr.id;}digit.points=[];digit.deps={};changed(true);toast('Iteration added to '+c.part+'. Image and calibration retained. Enter the next reference conditions and sample another curve.');}catch(e){toast(e.message);}});
