function csv(rows){return rows.map(row=>row.map(v=>{let s=v===null||v===undefined?'':String(v);return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}).join(',')).join('\n');}
function waveCSV(w){let keys=Object.keys(w.columns);return csv([keys,...Array.from({length:w.columns[keys[0]].length},(_,j)=>keys.map(k=>w.columns[k][j]))]);}
function summaryCSV(){return csv([['Combination','Operating point','Vin_V','Vout_V','Pout_W','Loss_W','Efficiency_pct','Valid',...CATEGORIES.map(k=>k+'_W'),'Warnings'],...orderedOperatingPoints(results.rows).map(r=>[r.combination,operatingPointLabel(r),r.vin,r.vout,r.outputPower,r.totalLoss,r.efficiency,r.valid,...CATEGORIES.map(k=>r.categories?.[k]),[...r.reasons,...r.devices.flatMap(d=>d.notes||[d.error])].filter(Boolean).join(' | ')])]);}
function deviceCSV(){return csv([['Combination','Operating point','Vin_V','Vout_V','Pout_W','Instance','Candidate','Series','Parallel','Device_count','Irms_per_device_A','Irms_total_mapped_A','Per_device_loss_W',...CATEGORIES.map(k=>k+'_W'),'Total_W','Temperature_C','Thermal_iterations','Thermal_residual_C','Status','Notes'],...orderedOperatingPoints(results.rows).flatMap(r=>r.devices.map(d=>[r.combination,operatingPointLabel(r),r.vin,r.vout,r.outputPower,d.instanceName,d.part,d.series,d.parallel,d.count,d.Irms,d.IrmsTotalMapped,d.perDeviceLoss,...CATEGORIES.map(k=>d.categories?.[k]),d.total,d.temperature,d.iterations,d.residual,d.valid?'valid':'failed',(d.notes||[d.error]).join(' | ')]))]);}
function reportDocument(){const settings=reportPreferences||{combinations:results.ranking.map(r=>r.combination),waveformIds:[...new Set(results.rows.map(r=>r.waveformId))],sections:{}};const view=selectReportResults(results,settings);const sections=settings.sections;const old=results;results=view;try{const body=`<h1>${esc(settings.title||p.name)}</h1>${settings.notes?`<p>${esc(settings.notes)}</p>`:''}<p><b>Report scope:</b> ${view.ranking.length} combinations · ${new Set(view.rows.map(r=>r.waveformId)).size} operating points. Metrics below refer to this selection.</p><p>Christian Verrecchia · Converter Loss Lab · Engine ${ENGINE_VERSION}<br>${esc(results.createdAt)}</p><p><b>Interpolation:</b> ${esc(INTERPOLATION_METHODS[p.operating.interpolationMethod||'reference-first'])} · domain policy: ${esc(p.operating.domainPolicy||'error')}</p><p><b>Model scope:</b> ${esc(scopeSummary())}</p>${p.importNotes?.map(n=>`<p>${esc(n)}</p>`).join('')||''}<h2>Alternative comparison · ascending combination order</h2>${table(['Combination','Parts','Mean efficiency %','Worst efficiency %','Mean loss W','Status'],orderedCombinations(results.ranking).map(r=>`<tr><td>${r.combination}</td><td>${esc(r.parts)}</td><td>${num(r.meanEfficiency,6)}</td><td>${num(r.worstEfficiency,6)}</td><td>${num(r.meanLoss,6)}</td><td>${r.valid?'Valid':'Incomplete / failed'}</td></tr>`))}${sections.efficiencyCharts!==false?`<h2>Efficiency</h2>${efficiencyGraph(results.rows)}${orderedCombinations(results.ranking).map(rank=>`<h2>Combination ${rank.combination}: efficiency by Vin / Vout pair</h2>${efficiencyGraph(results.rows.filter(r=>r.combination===rank.combination))}`).join('')}`:''}${comparisonVisuals(p,results,sections)}<h2>Operating-point results</h2>${table(['Combination','Operating point','Pout W','Loss W','Efficiency %','Status'],orderedOperatingPoints(results.rows).map(r=>`<tr><td>${r.combination}</td><td>${esc(operatingPointLabel(r))}</td><td>${num(r.outputPower,6)}</td><td>${num(r.totalLoss,6)}</td><td>${num(r.efficiency,6)}</td><td>${r.valid?'Valid':esc(r.reasons.join(' | '))}</td></tr>`))}${sections.deviceTable!==false?`<h2>Device results</h2>${deviceTable(results.rows)}`:''}${sections.diagnostics!==false?`<h2>Curve diagnostic details</h2>${diagnosticTable(results.rows)}`:''}${sections.sensitivity!==false&&sensitivity?`<h2>Sensitivity study</h2>${sensitivityResults(sensitivity)}<p>Sensitivity scope: combination ${sensitivity.combination}, ${sensitivity.operatingPoints} operating points; may differ from the report selection.</p>`:''}<h2>Calculation notes</h2>${notesHTML(results.rows)}<h2>Method limits</h2><p>Post-processed device-curve estimates; no measured accuracy or full MATLAB numerical parity has been established. Device alternatives share the imported waveforms. PWM core estimates and Qrr×V are approximations. Shared thermal coupling is not represented. Missing data does not become zero. Strict interpolation rejection is the default; returned warnings record fallback policies.</p><h2>Study settings</h2><pre>${esc(JSON.stringify(p.operating,null,2))}</pre>`;return `<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(p.name)} · Loss report</title><style>body{font:14px/1.6 system-ui,sans-serif;color:#192b38;margin:35px;--muted:#526575;--stroke:#dae0e5;--panel:white}h1{font-size:28px}h2{margin-top:30px}table{border-collapse:collapse;width:100%;font-size:11px}td,th{padding:7px;border:1px solid #ccd6de;text-align:left}.table-wrap{overflow:auto}.chart{max-width:900px;width:100%}.chart text{fill:#526575;font-size:11px}.chart .grid{stroke:#dae0e5}.chart .line{fill:none;stroke-width:2.5}.legend{display:flex;gap:18px;flex-wrap:wrap}.legend i{display:inline-block;width:8px;height:8px;margin-right:5px}.caption{font-size:12px}pre{white-space:pre-wrap;background:#f3f6f8;padding:15px}@page{size:A4 landscape;margin:12mm}.report-section{margin-top:30px}.chart{display:block;break-inside:avoid}.legend{font-size:11px;margin-bottom:18px}h2,h3{break-after:avoid}thead{display:table-header-group}@media print{body{margin:0;font-size:11px}tr,svg{break-inside:avoid}.report-section{break-before:page}.table-wrap{overflow:visible}th,td{padding:4px}.chart text{font-size:11px}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style><body>${body}</body></html>`;}finally{results=old;}}
function exportReport(){download(nameSafe(p.name)+'_report.html',reportDocument(),'text/html');}
function printReport(){const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-10000px;width:1100px;height:800px;border:0';frame.onload=()=>{frame.contentWindow.addEventListener('afterprint',()=>frame.remove(),{once:true});frame.contentWindow.focus();frame.contentWindow.print();};frame.srcdoc=reportDocument();document.body.append(frame);}
function startSensitivity(){try{const parameters=[...document.querySelectorAll('[data-sensitivity]:checked')].map(el=>el.dataset.sensitivity);if(!parameters.length)throw Error('Choose at least one parameter');const [instanceId,candidateId]=$('#sensitivityTarget').value.split(':'),row=results.rows.find(r=>r.combination===resultCombination&&r.valid);if(!row)throw Error('Choose a valid combination');const config={instanceId,candidateId,selection:Object.fromEntries(row.devices.map(d=>[d.instanceId,d.candidateId])),combination:resultCombination,waveformId:$('#sensitivityWave').value,percent:Number($('#sensitivityPercent').value),temperatureStep:Number($('#sensitivityTemperature').value),parameters};worker?.terminate();setRunning(true);$('#status').textContent='Running one-parameter sensitivity scenarios…';worker=new Worker('worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.progress!==undefined)$('#status').textContent='Sensitivity · '+Math.round(e.data.progress*100)+'%';else{worker.terminate();worker=null;setRunning(false);if(e.data.sensitivity){sensitivity=e.data.sensitivity;render();$('#status').textContent='Sensitivity complete · inspect coverage notes';}else toast(e.data.error);}};worker.onerror=e=>{worker?.terminate();worker=null;setRunning(false);toast('Sensitivity worker failed: '+e.message);};worker.postMessage({task:'sensitivity',project:p,config});}catch(e){toast(e.message);}}
function reportOptions(format){const previous=reportPreferences,points=[...new Map(orderedOperatingPoints(results.rows).map(r=>[r.waveformId,r])).values()],sections={efficiencyCharts:'Efficiency curves',comparisonCharts:'Combination comparison charts',lossCharts:'Loss breakdown at each operating point',componentCharts:'Component loss charts',maps:'Efficiency heatmaps',alternatives:'Component alternative comparisons',deviceTable:'Device result tables',diagnostics:'Detailed curve diagnostics',sensitivity:'Sensitivity results'};modal(`<div class="panel-head"><h2>Customise report</h2><button class="ghost small" data-close>×</button></div><p class="caption">Always included: selected-scope efficiency/loss metrics, operating-point summary, model scope, settings, warnings and method limits.</p><label>Report title<input id="reportTitle" value="${esc(previous?.title||p.name)}"></label><label>Notes<textarea id="reportNotes" rows="3">${esc(previous?.notes||'')}</textarea></label><h3>Combinations</h3><div class="scope-list">${orderedCombinations(results.ranking).map(r=>`<label class="check"><input type="checkbox" data-report-combination="${r.combination}" ${!previous||previous.combinations.includes(r.combination)?'checked':''}>#${r.combination} · ${esc(r.parts)}</label>`).join('')}</div><h3>Operating points</h3><div class="toolbar"><button class="ghost small" id="reportAllPoints">Select all</button><button class="ghost small" id="reportClearPoints">Clear</button></div><div style="max-height:240px;overflow:auto">${points.map(r=>`<label class="check"><input type="checkbox" data-report-wave="${r.waveformId}" ${!previous||previous.waveformIds.includes(r.waveformId)?'checked':''}>${esc(operatingPointLabel(r))}</label>`).join('')}</div><h3>Optional sections</h3><div class="scope-list">${Object.entries(sections).map(([key,label])=>`<label class="check"><input type="checkbox" data-report-section="${key}" ${previous?.sections[key]===false?'':'checked'} ${key==='sensitivity'&&!sensitivity?'disabled':''}>${label}</label>`).join('')}</div><div class="toolbar"><button class="primary" id="confirmReport">${format==='print'?'Print / save PDF':'Download HTML report'}</button><button class="ghost" data-close>Cancel</button></div>`);$('#reportAllPoints').onclick=()=>document.querySelectorAll('[data-report-wave]').forEach(el=>el.checked=true);$('#reportClearPoints').onclick=()=>document.querySelectorAll('[data-report-wave]').forEach(el=>el.checked=false);$('#confirmReport').onclick=()=>{try{const pref={title:$('#reportTitle').value,notes:$('#reportNotes').value,combinations:[...document.querySelectorAll('[data-report-combination]:checked')].map(el=>Number(el.dataset.reportCombination)),waveformIds:[...document.querySelectorAll('[data-report-wave]:checked')].map(el=>el.dataset.reportWave),sections:Object.fromEntries([...document.querySelectorAll('[data-report-section]')].map(el=>[el.dataset.reportSection,el.checked]))};selectReportResults(results,pref);reportPreferences=pref;$('#modal').close();if(format==='print')printReport();else exportReport();}catch(e){toast(e.message);}};}

function setRunning(on){$('#run').disabled=on;$('#cancelRun').hidden=!on;$('#run').innerHTML=on?'Calculating…':'Run analysis <span>↗</span>';}
function run(){sensitivity=null;reportPreferences=null;if(worker)worker.terminate();setRunning(true);$('#status').textContent='Validating models and computing alternatives…';worker=new Worker('worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.progress!==undefined)$('#status').textContent=`Calculating unique alternatives · ${Math.round(e.data.progress*100)}%`;else if(e.data.result){results=e.data.result;results.rows=orderedOperatingPoints(results.rows);worker.terminate();worker=null;setRunning(false);resultCombination=results.best?.combination||1;$('#status').textContent=`Analysis complete · ${results.combinationCount} combinations · ${results.errors.length} candidate/point failures`;render();toast(results.best?'Analysis complete. Results and exports are ready.':'Analysis completed with validation failures. Inspect results.');}else{worker.terminate();worker=null;setRunning(false);$('#status').textContent='Analysis stopped · '+e.data.error;toast(e.data.error);}};worker.onerror=e=>{setRunning(false);worker?.terminate();worker=null;toast('Calculation worker failed: '+e.message);};worker.postMessage(p);}
async function readJSONorMAT(file){return file.name.toLowerCase().endsWith('.mat')?await parseMat(await file.arrayBuffer()):JSON.parse(await file.text());}
async function importWaves(files){let batch=[],failures=[];for(const file of files){try{let w;if(/\.(csv|txt)$/i.test(file.name))w=parseDelimited(await file.text(),file.name);else{const raw=await readJSONorMAT(file);if(raw.schemaVersion===1){throw Error('Use Open project for a project JSON');}if(raw.columns){w={id:uid('wave'),name:file.name,...raw};}else{let numeric=Object.entries(raw).filter(([,v])=>Array.isArray(v)&&v.length&&Array.isArray(v[0])&&v[0].every(Number.isFinite));if(!numeric.length)throw Error('No numeric matrix found. Export MATLAB tables using export_loss_tool_web.m');let [key,data]=numeric.length===1?numeric[0]:await chooseMatrix(numeric);if(data.length<2)throw Error('Matrix has too few rows');let headers=Array.from({length:data[0].length},(_,j)=>'Var'+(j+1));w={id:uid('wave'),name:file.name+' · '+key,columns:Object.fromEntries(headers.map((h,j)=>[h,data.map(row=>row[j])])),time:headers[0],units:{}};}}
 batch.push(w);}catch(e){failures.push(file.name+': '+e.message);}}if(failures.length){modal(`<h2>Batch import could not continue</h2><p>Resolve these files and import the batch again.</p><ul>${failures.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><button class="ghost" data-close>Close</button>`);return;}try{const scan=scanWaveBatch(batch);if(scan.mismatches.length){modal(`<h2>Variable consistency check failed</h2><p>All files must contain the same variables. Column order can differ.</p>${table(['File','Missing variables'],scan.mismatches.map(w=>`<tr><td>${esc(w.name)}</td><td>${esc(w.missing.join(', '))}</td></tr>`))}<button class="ghost" data-close>Close</button>`);return;}const imported=await unitModal(batch);if(!imported)return;p.waveforms.push(...imported);selectedWave=imported[0].id;changed(true);toast(imported.length+' files imported with one shared units confirmation.');}catch(e){toast(e.message);}}
function chooseMatrix(entries){return new Promise(resolve=>{modal(`<div class="panel-head"><h2>Choose MAT variable</h2></div><select id="matrixVariable">${entries.map(([k,v],j)=>`<option value="${j}">${esc(k)} · ${v.length} × ${v[0].length}</option>`).join('')}</select><button class="primary" id="chooseMat">Import matrix</button>`);$('#chooseMat').onclick=()=>{let selected=entries[Number($('#matrixVariable').value)];$('#modal').close();resolve(selected);};$('#modal').addEventListener('cancel',()=>resolve(entries[0]),{once:true});});}
function unitModal(batch){return new Promise(resolve=>{let w=batch[0],keys=Object.keys(w.columns);modal(`<div class="panel-head"><h2>Confirm shared columns & units · ${batch.length} files</h2><button class="ghost small" id="cancelImport">Cancel</button></div><p class="caption">Consistency passed: all files have the same variables. Rename numeric MAT columns if needed. Choose time and confirm each variable’s unit once for the complete batch. Values are converted once to seconds, volts and amps.</p><label>Time column<select id="importTime">${options(keys,w.time)}</select></label>${table(['Column name','Unit'],keys.map((k,j)=>`<tr><td><input data-column="${j}" value="${esc(k)}"></td><td><select data-unit="${j}">${options(['s','ms','us','ns','V','mV','kV','A','mA','-'],w.units?.[k]|| (k===w.time?'s':/^i|current/i.test(k)?'A':'V'))}</select></td></tr>`))}<div class="toolbar"><button class="primary" id="confirmUnits">Import ${batch.length} waveforms</button></div>`);
 const cancel=()=>{$('#modal').close();resolve(null);};$('#cancelImport').onclick=cancel;$('#modal').addEventListener('cancel',()=>resolve(null),{once:true});$('#confirmUnits').onclick=()=>{try{let columns={},units={},renamed=[];keys.forEach((k,j)=>{const name=$(`[data-column="${j}"]`).value.trim();if(!name||name in columns)throw Error('Column names must be nonempty and unique');renamed.push(name);columns[name]=w.columns[k];units[name]=$(`[data-unit="${j}"]`).value;});let time=renamed[keys.indexOf($('#importTime').value)];if(!['s','ms','us','ns'].includes(units[time]))throw Error('Time column unit must be seconds, ms, us or ns');let out=batch.map(wave=>applyUnits({...wave,id:uid('wave'),columns:Object.fromEntries(keys.map((k,j)=>[renamed[j],wave.columns[k]]))},units,time));$('#modal').close();resolve(out);}catch(e){toast(e.message);}};});}
$('#waveFiles').onchange=e=>{importWaves([...e.target.files]);e.target.value='';};
$('#curveFiles').onchange=async e=>{let c=getCand();if(!c)return toast('Select a candidate first');for(const file of e.target.files){try{let raw=await readJSONorMAT(file),curves=[];if(raw.candidate||raw.candidates||(raw.curves&&raw.part)){alternativeImportDialog(raw);continue;}if(raw.curve)curves=[raw.curve];else if(raw.curves)curves=Array.isArray(raw.curves)?raw.curves:Object.values(raw.curves);else if(raw.characteristicId||raw.xName||raw.constant!==undefined)curves=[raw];else if(Array.isArray(raw))curves=raw;else throw Error('Select individual curve MAT files or a candidate/curve JSON');let converted=curves.map(cr=>canonicalCurve(cr)).map(cr=>({...cr,id:uid('curve')}));c.curves.push(...converted);changed(true);toast(converted.length+' characteristic(s) imported');}catch(err){toast(file.name+': '+err.message);}}e.target.value='';};
$('#projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let raw=await readJSONorMAT(file),q=raw.schemaVersion===1?raw:matlabStateToProject(raw);if(!Array.isArray(q.instances)||!Array.isArray(q.waveforms)||!q.operating)throw Error('Invalid project schema');p=hydrateProject(q);results=null;selectedInstance=null;selectedCandidate=null;selectedWave=null;changed(true);toast('Project loaded; results will be recomputed.');}catch(err){toast(err.message);}e.target.value='';};
$('#imageFile').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{digit={image:im,imageData:reader.result,calibration:[],points:[],stage:'calibrate',zoom:1,curveId:digit.curveId,group:digit.group};render();};im.src=reader.result;};reader.readAsDataURL(file);e.target.value='';};
$('#projectName').onchange=e=>{p.name=e.target.value.trim()||'Untitled study';changed();};$('#openProject').onclick=()=>$('#projectFile').click();$('#saveProject').onclick=()=>download(nameSafe(p.name)+'.json',JSON.stringify({...p,engineVersion:ENGINE_VERSION},null,2));$('#run').onclick=run;$('#cancelRun').onclick=()=>{worker?.terminate();worker=null;setRunning(false);$('#status').textContent='Analysis cancelled';};
$('#demo').onclick=()=>{if(p.waveforms.length&&!confirm('Replace the current study with synthetic demo data? Download your project first if you need a copy.'))return;p=demoProject();selectedInstance=null;selectedCandidate=null;selectedWave=null;changed();location.hash='overview';render();run();};$('#newProject').onclick=()=>{if(p.waveforms.length&&!confirm('Start a new study? Download your current project first if you need a copy.'))return;p=emptyProject();selectedInstance=null;selectedCandidate=null;selectedWave=null;changed();location.hash='overview';render();};window.addEventListener('hashchange',render);render();if(p.waveforms.every(w=>w.demo)&&p.waveforms.length)run();

function alternativeImportDialog(raw){const sources=raw.candidate?[raw.candidate]:raw.candidates||[raw];let sourceIndex=0;const current=getInst();let type=raw.componentType||raw.type||current?.type||'MOSFET';function draw(){if($('#modal').open)$('#modal').close();const source=sources[sourceIndex];if(!source||!Array.isArray(source.curves))throw Error('This file does not contain alternative characteristics');modal(`<div class="panel-head"><h2>Reuse alternative characteristics</h2><button data-close class="ghost">×</button></div><label>Part / alternative in file<select id="importSource">${sources.map((c,j)=>`<option value="${j}" ${j===sourceIndex?'selected':''}>${esc(c.part||'Alternative '+(j+1))}</option>`).join('')}</select></label><label>Component type<select id="importType" ${(raw.componentType||raw.type)?'disabled':''}>${options(['MOSFET','Diode','Capacitor','Inductor'],type)}</select></label><label>Destination<select id="importDestination">${current&&current.type===type?`<option value="new">New alternative in ${esc(current.name)}</option><option value="existing">Add characteristics to ${esc(getCand().part||'selected alternative')}</option>`:''}<option value="instance">New component</option></select></label><h3>Characteristics to import</h3>${source.curves.map((cr,j)=>`<label class="check"><input type="checkbox" data-import-characteristic="${j}" checked>${esc(cr.sourceId?characteristicName(cr.sourceId):cr.yName+' vs '+cr.xName)} · ${cr.iterations?.length||0} iterations</label>`).join('')}<p class="caption">Only the selected characteristics and their measured reference conditions are reused. Configure series/parallel counts, gate settings, enabled losses, thermal settings and waveform mappings yourself. Existing alternative settings are preserved.</p><button class="primary" id="confirmAlternativeImport">Import selected characteristics</button><button class="ghost" data-close>Cancel</button>`);$('#importSource').onchange=e=>{sourceIndex=Number(e.target.value);draw();};$('#importType').onchange=e=>{type=e.target.value;draw();};$('#confirmAlternativeImport').onclick=()=>{try{const indices=[...document.querySelectorAll('[data-import-characteristic]:checked')].map(el=>Number(el.dataset.importCharacteristic));const imported=importAlternative(raw,type,sourceIndex,indices),destination=$('#importDestination').value;let target=current,candidate;if(destination==='instance'){target=makeInstance(type);target.name=imported.part||type;target.candidates=[];}candidate=destination==='existing'?getCand():blankCandidate(type);if(destination!=='existing')candidate.part=imported.part;candidate.curves.push(...imported.curves);if(destination!=='existing')target.candidates.push(candidate);if(destination==='instance')p.instances.push(target);selectedInstance=target.id;selectedCandidate=candidate.id;subtab='curves';$('#modal').close();changed(true);toast(imported.curves.length+' characteristics imported. Configure the alternative settings before analysis.');}catch(error){toast(error.message);}};}draw();}
$('#componentFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{alternativeImportDialog(JSON.parse(await file.text()));}catch(error){toast(error.message);}finally{e.target.value='';}};
